/* « En un coup d'œil » : un grand schéma qui résume une notion (modèle : les quadrilatères particuliers de M. Staal).
   window.CARTES["5e-4"] = "<div class='cmap'>…</div>" ; la feuille de style est injectée une seule fois. */
(function(){
const CSS=`
.cmap{--def:#c62828;--defbg:#fdecec;--prop:#1f8a3c;--propbg:#eaf7ee;--meth:#1e5aa8;--methbg:#e8f0fb;--ink:#15213b;
  background:#fff;color:var(--ink);font-family:Arial,"Liberation Sans",Helvetica,sans-serif;font-size:15px;line-height:1.35;
  border-radius:14px;padding:18px 20px;min-width:820px;box-sizing:border-box}
.cmap *{box-sizing:border-box}
.cmap-scroll{overflow-x:auto;border:1px solid var(--line,#d3dbea);border-radius:14px;background:#fff;width:min(1180px,calc(100vw - 48px));position:relative;left:50%;transform:translateX(-50%);margin:12px 0}
.cmap .cm-top{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;margin:0 0 14px}
.cmap .cm-title{font-size:24px;font-weight:700;margin:0;color:var(--ink)}
.cmap .cm-legend{display:flex;gap:10px;align-items:center;font-weight:700;font-size:14px}
/* pastilles et boîtes */
.cmap .cm-pill{display:inline-block;border:2px solid var(--k,#999);background:var(--kb,#fff);color:var(--k,#333);font-weight:700;border-radius:999px;padding:4px 16px}
.cmap .cm-pill.def{--k:var(--def);--kb:var(--defbg)} .cmap .cm-pill.prop{--k:var(--prop);--kb:var(--propbg)} .cmap .cm-pill.meth{--k:var(--meth);--kb:var(--methbg)}
.cmap .cm-box{border:2px solid var(--k);background:var(--kb);border-radius:18px;padding:10px 12px;text-align:center;font-size:14.5px;display:flex;align-items:center;justify-content:center;min-height:62px}
.cmap .cm-box.def{--k:var(--def);--kb:var(--defbg);color:#7a1414} .cmap .cm-box.prop{--k:var(--prop);--kb:var(--propbg);color:#14532d} .cmap .cm-box.meth{--k:var(--meth);--kb:var(--methbg);color:#123a6b}
.cmap .cm-box.neutre{--k:#94a3b8;--kb:#f8fafc}
.cmap .cm-box b{color:inherit}
/* zones (cadres arrondis colorés, emboîtables) */
.cmap .cm-zone{position:relative;border:3px solid var(--z,#2563eb);background:color-mix(in srgb,var(--z,#2563eb) 7%,#fff);border-radius:22px;padding:12px}
.cmap .cm-zone.dash{border-style:dashed}
.cmap .cm-tag{display:inline-flex;align-items:center;gap:10px;background:var(--z,#2563eb);color:#fff;font-weight:700;font-size:16px;letter-spacing:.02em;border-radius:999px;padding:5px 16px;margin:0 0 10px}
.cmap .cm-tag svg{display:block}
.cmap .cm-row{display:grid;gap:12px;grid-template-columns:repeat(var(--n,4),minmax(0,1fr));align-items:stretch}
.cmap .cm-col{display:flex;flex-direction:column;gap:12px}
.cmap .cm-big{font-size:20px;font-weight:700}
.cmap .cm-note{font-size:13px;color:#475569;margin:8px 0 0}
.cmap .cm-fig{display:inline-block;vertical-align:middle}
/* flèches entre boîtes */
.cmap .cm-arrow{display:flex;align-items:center;justify-content:center;font-size:22px;color:#64748b;font-weight:700}
/* Venn à 3 colonnes : deux zones qui se chevauchent sur la colonne du milieu */
.cmap .cm-venn{display:grid;grid-template-columns:1fr 1fr 1fr;gap:0 18px;position:relative}
.cmap .cm-venn > .cm-frame{grid-row:1;border:3px solid var(--z);background:color-mix(in srgb,var(--z) 9%,transparent);border-radius:20px;margin:0 -9px}
.cmap .cm-venn > .cm-cell{grid-row:1;position:relative;z-index:1;padding:12px 10px;display:flex;flex-direction:column;gap:12px}
@media print{.cmap-scroll{border:0;overflow:visible}}
.sheet .cmap{min-width:0;padding:0}
`;
if(!document.getElementById('cmap-css')){ const s=document.createElement('style'); s.id='cmap-css'; s.textContent=CSS; document.head.appendChild(s); }
window.CARTES=window.CARTES||{};
})();

CARTES["3e-1"]="<div class=\"cmap\"><div class=\"cm-top\"><p class=\"cm-title\">L'arithmétique</p><div class=\"cm-legend\">Légende : <span class=\"cm-pill def\">Définition</span><span class=\"cm-pill prop\">Propriété</span><span class=\"cm-pill meth\">Méthode</span></div></div><div style=\"display:grid;grid-template-columns:0.86fr 1.5fr 0.98fr;gap:14px;align-items:stretch\"><div class=\"cm-zone\" style=\"--z:#1e5aa8;display:flex;flex-direction:column;gap:10px\"><span class=\"cm-tag\" style=\"align-self:flex-start;margin:0\">MULTIPLES ET DIVISEURS</span><div style=\"text-align:center;background:#fff;border-radius:14px;padding:10px 6px;border:1.5px solid #cfe0ff\"><div style=\"font-size:28px;font-weight:700;letter-spacing:.02em\"><span style=\"color:#db2777\">12</span> × 2 = <span style=\"color:#7c3aed\">24</span></div><div style=\"font-size:15px;line-height:1.55;margin-top:4px\"><b style=\"color:#7c3aed\">24</b> est un <b>multiple</b> de <b style=\"color:#db2777\">12</b><br><b style=\"color:#db2777\">12</b> est un <b>diviseur</b> de <b style=\"color:#7c3aed\">24</b><br><b style=\"color:#7c3aed\">24</b> est <b>divisible par</b>&#32;<b style=\"color:#db2777\">12</b></div></div><div class=\"cm-box def\" style=\"min-height:0\"><span><i>a</i> est un <b>multiple</b> de <i>b</i> s'il existe un <b>entier</b> tel que <i>b</i> × entier = <i>a</i>.</span></div><div style=\"font-size:14px;text-align:center;color:#334155\">Diviseurs de 12 : 1, 2, 3, 4, 6 et 12<br>Multiples de 12 : 0, 12, 24, 36…</div></div><div class=\"cm-zone\" style=\"--z:#2563eb;display:flex;flex-direction:column;gap:8px\"><span class=\"cm-tag\" style=\"align-self:flex-start;margin:0\">CRITÈRES DE DIVISIBILITÉ</span><div style=\"font-weight:700;color:#2563eb;font-size:14.5px\">On regarde le <u>dernier chiffre</u> :</div><div style=\"display:flex;align-items:center;gap:10px;background:#fff;border-radius:12px;padding:5px 10px;border:1.5px solid #cfe0ff\"><span style=\"flex:none;width:58px;text-align:center;font-weight:700;font-size:15px;color:#fff;background:#2563eb;border-radius:999px;padding:3px 0\">par 2</span><span style=\"font-size:14.5px;flex:1\"><b>pair</b> : se termine par 0, 2, 4, 6 ou 8</span><span style=\"font-size:13px;color:#475569;white-space:nowrap\">ex. : 276</span></div><div style=\"display:flex;align-items:center;gap:10px;background:#fff;border-radius:12px;padding:5px 10px;border:1.5px solid #cfe0ff\"><span style=\"flex:none;width:58px;text-align:center;font-weight:700;font-size:15px;color:#fff;background:#2563eb;border-radius:999px;padding:3px 0\">par 5</span><span style=\"font-size:14.5px;flex:1\">se termine par <b>0 ou 5</b></span><span style=\"font-size:13px;color:#475569;white-space:nowrap\">ex. : 845</span></div><div style=\"display:flex;align-items:center;gap:10px;background:#fff;border-radius:12px;padding:5px 10px;border:1.5px solid #cfe0ff\"><span style=\"flex:none;width:58px;text-align:center;font-weight:700;font-size:15px;color:#fff;background:#2563eb;border-radius:999px;padding:3px 0\">par 10</span><span style=\"font-size:14.5px;flex:1\">se termine par <b>0</b></span><span style=\"font-size:13px;color:#475569;white-space:nowrap\">ex. : 840</span></div><div style=\"font-weight:700;color:#2563eb;font-size:14.5px;margin-top:2px\">On fait la <u>somme des chiffres</u> :</div><div style=\"display:flex;align-items:center;gap:10px;background:#fff;border-radius:12px;padding:5px 10px;border:1.5px solid #cfe0ff\"><span style=\"flex:none;width:58px;text-align:center;font-weight:700;font-size:15px;color:#fff;background:#2563eb;border-radius:999px;padding:3px 0\">par 3</span><span style=\"font-size:14.5px;flex:1\">somme des chiffres : <b>multiple de 3</b></span><span style=\"font-size:13px;color:#475569;white-space:nowrap\">276 : 2 + 7 + 6 = 15</span></div><div style=\"display:flex;align-items:center;gap:10px;background:#fff;border-radius:12px;padding:5px 10px;border:1.5px solid #cfe0ff\"><span style=\"flex:none;width:58px;text-align:center;font-weight:700;font-size:15px;color:#fff;background:#2563eb;border-radius:999px;padding:3px 0\">par 9</span><span style=\"font-size:14.5px;flex:1\">somme des chiffres : <b>multiple de 9</b></span><span style=\"font-size:13px;color:#475569;white-space:nowrap\">576 : 5 + 7 + 6 = 18</span></div></div><div class=\"cm-zone\" style=\"--z:#c2410c;display:flex;flex-direction:column;gap:10px\"><span class=\"cm-tag\" style=\"align-self:flex-start;margin:0\">NOMBRES PREMIERS</span><div class=\"cm-box def\" style=\"min-height:0\"><span>Un <b>nombre premier</b> a <b>exactement deux diviseurs</b> distincts : <b>1 et lui-même</b>.</span></div><div style=\"text-align:center;line-height:1.1\"><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">2</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">3</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">5</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">7</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">11</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">13</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">17</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">19</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">23</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">29</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">31</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">37</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">41</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">43</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">47</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">53</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">59</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">61</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">67</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">71</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">73</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">79</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">83</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">89</span><span style=\"display:inline-block;min-width:29px;text-align:center;padding:3px 0;margin:2px 1.5px;border-radius:8px;background:#fff;border:1.5px solid color-mix(in srgb,#c2410c 50%,#fff);font-weight:700;font-size:13.5px;color:#9a3412\">97</span></div><div style=\"font-size:13px;text-align:center;color:#475569;margin-top:-4px\">les nombres premiers inférieurs à 100</div><div style=\"display:grid;grid-template-columns:1fr;gap:6px\"><div class=\"cm-box neutre\" style=\"min-height:0;font-size:14px;padding:6px 8px\"><span><b>4</b> n'est pas premier : 3 diviseurs (1, 2 et 4)</span></div><div class=\"cm-box neutre\" style=\"min-height:0;font-size:14px;padding:6px 8px;--k:#c2410c\"><span><b>ATTENTION : 1</b> n'est pas premier (un seul diviseur)</span></div></div></div></div><div style=\"display:grid;grid-template-columns:0.95fr 1.05fr 1fr;gap:14px;align-items:stretch;margin-top:14px\"><div class=\"cm-zone\" style=\"--z:#c2410c;display:flex;flex-direction:column;gap:6px\"><span class=\"cm-tag\" style=\"align-self:flex-start;margin:0;font-size:15px\">DÉCOMPOSITION EN FACTEURS PREMIERS</span><div style=\"text-align:center\"><svg width=\"380\" height=\"180\" viewBox=\"0 0 380 180\" ><line x1=\"116.28\" y1=\"25.23\" x2=\"83.72\" y2=\"44.77\" stroke=\"#94a3b8\" stroke-width=\"2\" /><line x1=\"144.05\" y1=\"24.66\" x2=\"181.95\" y2=\"45.34\" stroke=\"#94a3b8\" stroke-width=\"2\" /><line x1=\"182.28\" y1=\"61.23\" x2=\"149.72\" y2=\"80.77\" stroke=\"#94a3b8\" stroke-width=\"2\" /><line x1=\"209.72\" y1=\"61.23\" x2=\"242.28\" y2=\"80.77\" stroke=\"#94a3b8\" stroke-width=\"2\" /><line x1=\"242.54\" y1=\"97.65\" x2=\"213.46\" y2=\"116.35\" stroke=\"#94a3b8\" stroke-width=\"2\" /><line x1=\"269.31\" y1=\"97.88\" x2=\"296.69\" y2=\"116.12\" stroke=\"#94a3b8\" stroke-width=\"2\" /><line x1=\"298.11\" y1=\"135.7\" x2=\"281.89\" y2=\"150.3\" stroke=\"#94a3b8\" stroke-width=\"2\" /><line x1=\"321.89\" y1=\"135.7\" x2=\"338.11\" y2=\"150.3\" stroke=\"#94a3b8\" stroke-width=\"2\" /><text x=\"130\" y=\"23\" font-size=\"18\" fill=\"#15213b\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >300</text><text x=\"196\" y=\"59\" font-size=\"18\" fill=\"#15213b\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >150</text><text x=\"256\" y=\"95\" font-size=\"18\" fill=\"#15213b\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >75</text><text x=\"310\" y=\"131\" font-size=\"18\" fill=\"#15213b\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >25</text><circle cx=\"70\" cy=\"53\" r=\"15\" fill=\"#ffe8cc\" stroke=\"#c2410c\" stroke-width=\"2.2\"/><text x=\"70\" y=\"59\" font-size=\"17\" fill=\"#9a3412\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >2</text><circle cx=\"136\" cy=\"89\" r=\"15\" fill=\"#ffe8cc\" stroke=\"#c2410c\" stroke-width=\"2.2\"/><text x=\"136\" y=\"95\" font-size=\"17\" fill=\"#9a3412\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >2</text><circle cx=\"200\" cy=\"125\" r=\"15\" fill=\"#ffe8cc\" stroke=\"#c2410c\" stroke-width=\"2.2\"/><text x=\"200\" y=\"131\" font-size=\"17\" fill=\"#9a3412\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >3</text><circle cx=\"270\" cy=\"161\" r=\"15\" fill=\"#ffe8cc\" stroke=\"#c2410c\" stroke-width=\"2.2\"/><text x=\"270\" y=\"167\" font-size=\"17\" fill=\"#9a3412\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >5</text><circle cx=\"350\" cy=\"161\" r=\"15\" fill=\"#ffe8cc\" stroke=\"#c2410c\" stroke-width=\"2.2\"/><text x=\"350\" y=\"167\" font-size=\"17\" fill=\"#9a3412\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >5</text></svg></div><div style=\"text-align:center;font-size:20px;font-weight:700\">300 = 2 × 2 × 3 × 5 × 5 = 2<sup>2</sup> × 3 × 5<sup>2</sup></div><div class=\"cm-box prop\" style=\"min-height:0\"><span>Un nombre non premier se décompose <b>toujours</b> en <b>produit de facteurs premiers</b>, et cette décomposition est <b>unique</b>.</span></div></div><div class=\"cm-zone\" style=\"--z:#1f8a3c;display:flex;flex-direction:column;gap:6px\"><span class=\"cm-tag\" style=\"align-self:flex-start;margin:0\">PLUS GRAND DIVISEUR COMMUN</span><div style=\"text-align:center;font-size:14px;line-height:1.4\"><b style=\"color:#7c3aed\">900 = 2 × 2 × 3 × 3 × 5 × 5</b><br><b style=\"color:#db2777\">350 = 2 × 5 × 5 × 7</b></div><div style=\"text-align:center;margin-top:-4px\"><svg width=\"380\" height=\"186\" viewBox=\"0 0 380 186\" style=\"width:300px;height:auto\"><ellipse cx=\"128\" cy=\"98\" rx=\"112\" ry=\"82\" fill=\"#7c3aed\" fill-opacity=\".10\" stroke=\"#7c3aed\" stroke-width=\"2.5\"/><ellipse cx=\"252\" cy=\"98\" rx=\"112\" ry=\"82\" fill=\"#db2777\" fill-opacity=\".10\" stroke=\"#db2777\" stroke-width=\"2.5\"/><text x=\"64\" y=\"26\" font-size=\"18\" fill=\"#7c3aed\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >900</text><text x=\"316\" y=\"26\" font-size=\"18\" fill=\"#db2777\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >350</text><circle cx=\"62\" cy=\"82\" r=\"15\" fill=\"#fff\" stroke=\"#7c3aed\" stroke-width=\"2\"/><text x=\"62\" y=\"88\" font-size=\"17\" fill=\"#7c3aed\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >2</text><circle cx=\"96\" cy=\"118\" r=\"15\" fill=\"#fff\" stroke=\"#7c3aed\" stroke-width=\"2\"/><text x=\"96\" y=\"124\" font-size=\"17\" fill=\"#7c3aed\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >3</text><circle cx=\"56\" cy=\"128\" r=\"15\" fill=\"#fff\" stroke=\"#7c3aed\" stroke-width=\"2\"/><text x=\"56\" y=\"134\" font-size=\"17\" fill=\"#7c3aed\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >3</text><circle cx=\"190\" cy=\"62\" r=\"15\" fill=\"#eaf7ee\" stroke=\"#1f8a3c\" stroke-width=\"2\"/><text x=\"190\" y=\"68\" font-size=\"17\" fill=\"#1f8a3c\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >2</text><circle cx=\"176\" cy=\"104\" r=\"15\" fill=\"#eaf7ee\" stroke=\"#1f8a3c\" stroke-width=\"2\"/><text x=\"176\" y=\"110\" font-size=\"17\" fill=\"#1f8a3c\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >5</text><circle cx=\"204\" cy=\"140\" r=\"15\" fill=\"#eaf7ee\" stroke=\"#1f8a3c\" stroke-width=\"2\"/><text x=\"204\" y=\"146\" font-size=\"17\" fill=\"#1f8a3c\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >5</text><circle cx=\"318\" cy=\"104\" r=\"15\" fill=\"#fff\" stroke=\"#db2777\" stroke-width=\"2\"/><text x=\"318\" y=\"110\" font-size=\"17\" fill=\"#db2777\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"Arial,Helvetica,sans-serif\" >7</text></svg></div><div style=\"text-align:center;font-size:19px;font-weight:700;color:#14532d\">facteurs communs : 2 × 5 × 5 = 50</div><div class=\"cm-box meth\" style=\"min-height:0\"><span>On ne prend que les facteurs premiers présents <b>dans les deux décompositions</b> et on les <b>multiplie</b> : le plus grand diviseur commun à 900 et 350 est <b>50</b>.</span></div></div><div class=\"cm-zone\" style=\"--z:#1e5aa8;display:flex;flex-direction:column;gap:10px\"><span class=\"cm-tag\" style=\"align-self:flex-start;margin:0\">PROBLÈMES DE PARTAGE</span><div class=\"cm-box prop\" style=\"min-height:0\"><span>Pour faire le <b>plus grand nombre</b> de paquets identiques <b>en utilisant tout</b>, on cherche le <b>plus grand diviseur commun</b> aux deux nombres.</span></div><div style=\"background:#fff;border-radius:14px;border:1.5px solid #cfe0ff;padding:10px 12px;font-size:14.5px;line-height:1.5\"><b>434 roses et 620 tulipes</b> : le plus de bouquets identiques ?<br>\n   434 = <b>2</b> × 7 × <b>31</b><br>620 = <b>2</b> × 2 × 5 × <b>31</b><br>\n   Plus grand diviseur commun : <b>2 × 31 = 62</b><br><span style=\"display:inline-block;margin-top:4px;padding:4px 10px;border-radius:10px;background:#eaf7ee;color:#14532d\"><b>62 bouquets</b> de <b>7 roses</b> et <b>10 tulipes</b><br><span style=\"font-size:13px\">car 434 ÷ 62 = 7 et 620 ÷ 62 = 10</span></span></div></div></div></div>";
